def sha(path: Path) -> str | None:
    if not path.exists():
        return None
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def route_signature(root: Path) -> list[tuple[str, str, str]]:
    pattern = re.compile(r'@router\.(get|post|put|delete|patch)\(\s*["\']([^"\']+)["\']')
    result = []
    for path in sorted((root / "app" / "routers").glob("*.py")):
        text = path.read_text(encoding="utf-8-sig")
        for method, route in pattern.findall(text):
            result.append((path.name, method, route))
    return result


def backup_file(path: Path, manifest: dict) -> None:
    rel = path.relative_to(PROJECT).as_posix()
    existed = path.exists()
    manifest[rel] = {"existed": existed}
    if existed:
        dest = BACKUP / rel
        dest.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, dest)


def restore(manifest: dict) -> None:
    print("\nDANG KHOI PHUC TRANG THAI TRUOC KHI SUA...")
    for rel, info in manifest.items():
        target = PROJECT / rel
        saved = BACKUP / rel
        if info.get("existed"):
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(saved, target)
        elif target.exists():
            target.unlink()
    print("DA KHOI PHUC AN TOAN.")


def remove_old_multi_block(text: str) -> str:
    pattern = re.compile(
        re.escape(MARKER_START) + r".*?" + re.escape(MARKER_END) + r"\s*\n?",
        re.S,
    )
    return pattern.sub("", text)


def patch_router(text: str) -> str:
    # Luon tao lai nhanh xuat 12 bieu tren CHINH route xuat Excel hien co.
    text = remove_old_multi_block(text)

    for code in REPORT_CODES:
        if f'"{code}"' not in text:
            raise RuntimeError(
                f"Chua co danh muc bao cao {code}. Hay cai PCGD & XMC V1.5 truoc."
            )

    route_anchor = '@router.get("/xuat-danh-muc-excel")'
    route_pos = text.find(route_anchor)
    if route_pos < 0:
        raise RuntimeError("Khong tim thay route /bao-cao/xuat-danh-muc-excel hien co.")

    next_decorator = text.find("\n@router.", route_pos + len(route_anchor))
    if next_decorator < 0:
        next_decorator = len(text)
    segment = text[route_pos:next_decorator]

    rows_anchor = "    rows, summary = _build_report_rows("
    local_pos = segment.find(rows_anchor)
    if local_pos < 0:
        raise RuntimeError("Khong tim thay vi tri lap danh muc trong route xuat Excel.")
    insert_pos = route_pos + local_pos

    block = """    # === PCGD_XMC_MULTI_REPORT_V1_START ===
    # 12 bieu moi dung lai route xuat Excel hien co. Neu dung ma bao cao moi,
    # tra ve CHINH mau Excel goc; neu khong thi luong xuat danh muc cu tiep tuc nhu truoc.
    from app.pcgd_xmc_report_builders_v1 import (
        SUPPORTED_REPORT_TYPES as PCGD_XMC_SUPPORTED_REPORT_TYPES,
        export_additional_report as export_pcgd_xmc_additional_report,
    )
    if normalized_report_type in PCGD_XMC_SUPPORTED_REPORT_TYPES:
        return export_pcgd_xmc_additional_report(
            report_type=normalized_report_type,
            db=db,
            request=request,
            school_year=selected_year,
            selected_commune_id=selected_commune_id,
            selected_school_id=selected_school_id,
            scope_label=scope_label,
        )
    # === PCGD_XMC_MULTI_REPORT_V1_END ===

"""
    text = text[:insert_pos] + block + text[insert_pos:]

    for code in REPORT_CODES:
        pattern = rf'("{re.escape(code)}"\s*:\s*\{{.*?\n\s*\}},)'
        m = re.search(pattern, text, re.S)
        if not m:
            continue
        old = m.group(1)
        new = re.sub(
            r'"stage":\s*"[^"]*"',
            '"stage": "Sẵn sàng V1.1 – xuất đúng mẫu Excel"',
            old,
            count=1,
        )
        new = re.sub(
            r'"stage_class":\s*"[^"]*"',
            '"stage_class": "ready"',
            new,
            count=1,
        )
        text = text[:m.start(1)] + new + text[m.end(1):]
    return text


def patch_html(text: str) -> str:
    codes = ",".join(repr(code) for code in REPORT_CODES)
    all_codes = "'PCGD_TH_M1_2025'," + codes
    new_block = (
        "{% if selected_report_type in [" + all_codes + "] %}\n"
        "                <a class=\"button button-success\" href=\"{{ export_url }}\">📘 Xuất biểu {{ selected_report.short_title }} Excel</a>\n"
        "                {% else %}\n"
        "                <a class=\"button button-success\" href=\"{{ export_url }}\">📊 Xuất danh mục Excel</a>\n"
        "                {% endif %}"
    )

    pat_thm1 = re.compile(
        r"\{%\s*if\s+selected_report_type\s*==\s*'PCGD_TH_M1_2025'\s*%\}.*?"
        r"<a class=\"button button-success\" href=\"\{\{ export_url \}\}\">📊 Xuất danh mục Excel</a>\s*"
        r"\{%\s*endif\s*%\}",
        re.S,
    )
    if pat_thm1.search(text):
        return pat_thm1.sub(new_block, text, count=1)

    pat_multi = re.compile(
        r"\{%\s*if\s+(?:selected_report_type|report_type)\s+in\s*\[.*?\]\s*%\}.*?"
        r"<a class=\"button button-success\" href=\"\{\{ export_url \}\}\">📊 Xuất danh mục Excel</a>\s*"
        r"\{%\s*endif\s*%\}",
        re.S,
    )
    if pat_multi.search(text):
        return pat_multi.sub(new_block, text, count=1)

    old_button = '<a class="button button-success" href="{{ export_url }}">📊 Xuất danh mục Excel</a>'
    if old_button in text:
        return text.replace(old_button, new_block, 1)

    raise RuntimeError("Khong tim thay khoi nut xuat Excel de sua an toan.")


